61	/**
62	 * Gestione asset di un singolo record (digital-hub #16).
63	 *
64	 * Page record-scoped, full-width, fuori dalla navigazione: si raggiunge solo
65	 * dall'azione {@see \AtrioTeam\DigitalHub\Assets\Filament\Actions\ManageAssetsAction}
66	 * nella tabella di una resource. La route porta owner via coppia polimorfica
67	 * (morph alias + chiave): `/assets/{ownerType}/{owner}`, così la pagina è
68	 * generica per qualunque modello che usa il trait HasAssets, non solo Product.
69	 *
70	 * Lo stato dell'UI (folder attiva, ecc.) sarà aggiunto negli step successivi
71	 * di #16a; qui c'è solo lo scheletro navigabile.
72	 */
73	class AssetManager extends Page implements HasActions
74	{
75	    use InteractsWithActions;
76	
77	    protected static string|BackedEnum|null $navigationIcon = Heroicon::OutlinedFolderOpen;
78	
79	    protected static ?string $slug = 'assets';
80	
81	    protected string $view = 'digital-hub::filament.pages.asset-manager';
82	
83	    protected Width|string|null $maxContentWidth = Width::Full;
84	
85	    /**
86	     * Layout "base" (solo body, niente sidebar/topbar): la pagina è un editor di
87	     * asset a tutto schermo, presentato come un "finto modal" che si chiude con la
88	     * X tornando al catalogo (vedi blade). Il layout base include comunque gli
89	     * stili/script Filament e il componente notifiche, quindi toast e modali delle
90	     * action continuano a funzionare.
91	     */
92	    protected static string $layout = 'filament-panels::components.layout.base';
93	
94	    /** icona di "sposta", usata per file e cartelle */
95	    protected Heroicon $moveActionIcon = Heroicon::OutlinedArrowUpOnSquareStack;
96	
97	    /** Morph alias del record proprietario (es. `product`). */
98	    public string $ownerType;
99	
100	    /** Chiave primaria del record proprietario. */
101	    public int|string $ownerKey;
102	
103	    /** Folder attualmente selezionata; null = root ("Home") del record. */
104	    public ?int $activeFolderId = null;
105	
106	    /**
107	     * URL della lista da cui si è arrivati (catturato dal Referer alla mount),
108	     * per il link "indietro". null se assente o non locale. È public così
109	     * sopravvive alle update Livewire successive (la mount gira una sola volta).
110	     */
111	    public ?string $returnUrl = null;
112	
113	    /**
114	     * Id dei media selezionati per le azioni multiple (checkbox sulle card).
115	     * @var array<int, int|string>
116	     */
117	    public array $selectedAssetIds = [];
118	
119	    /**
120	     * Id delle sottocartelle selezionate per le azioni multiple (checkbox sulle
121	     * tile cartella). Una cartella selezionata vale come "tutti i media del suo
122	     * sottoalbero" per scarica/condividi; sposta/elimina multipli restano
123	     * solo-file (nascosti quando ci sono cartelle in selezione).
124	     * @var array<int, int|string>
125	     */
126	    public array $selectedFolderIds = [];
127	
128	    /** URL dell'ultimo share creato, mostrato nel modal "share-link" (22g). */
129	    public ?string $lastShareUrl = null;
130	
131	    /**
132	     * Cache per-request del record risolto (privata: non serializzata da Livewire).
133	     * @var (Model&OwnsAssets)|null
134	     */
135	    private ?Model $ownerModel = null;
136	
137	    /**
138	     * Cache per-request delle folder del record (privata: non serializzata da Livewire).
139	     * @var null|EloquentCollection<int,AssetFolder>
140	     */
141	    private ?EloquentCollection $folderCache = null;
142	
143	    /**
144	     * Cache per-request dei media contenuti nei sottoalberi delle sottocartelle
145	     * visibili, condivisa tra preview delle tile cartella e check del polling.
146	     * @var null|\Illuminate\Support\Collection<int, Media>
147	     */
148	    private ?\Illuminate\Support\Collection $subfolderMediaCache = null;
149	
150	    #[Override]
151	    public static function getRoutePath(Panel $panel): string
152	    {
153	        return '/assets/{ownerType}/{owner}';
154	    }
155	
156	    public static function shouldRegisterNavigation(): bool
157	    {
158	        return false;
159	    }
160	
161	    /**
162	     * I parametri di route (ownerType, owner) sono iniettati da Livewire.
163	     */
164	    public function mount(string $ownerType, int|string $owner): void
165	    {
166	        $this->ownerType = $ownerType;
167	        $this->ownerKey = $owner;
168	
169	        // valida subito: record risolvibile e dotato del trait HasAssets
170	        $this->resolveOwner();
171	
172	        // la lista di provenienza (con i suoi filtri, es. sottocategoria) è
173	        // esattamente la pagina che ha linkato qui: la prendiamo dal Referer.
174	        // Fallback (link diretto/tab nuova, niente referer): la lista della
175	        // resource del record, senza filtri.
176	        $this->returnUrl = $this->resolveReturnUrl(request()->headers->get('referer'))
177	            ?? $this->resourceIndexUrl();
178	    }
179	
180	    /**
181	     * Valida l'URL di ritorno: accetta solo URL dello stesso host dell'app (no
182	     * open redirect verso domini esterni) e scarta l'auto-riferimento alla
183	     * pagina asset stessa (es. reload). null se non valido.
184	     */
185	    private function resolveReturnUrl(?string $url): ?string
186	    {
187	        if (! is_string($url) || $url === '') {
188	            return null;
189	        }
190	
191	        $host = parse_url($url, PHP_URL_HOST);
192	        if ($host !== null && $host !== request()->getHost()) {
193	            return null;
194	        }
195	
196	        // non puntare a sé stessa (la pagina asset): eviterebbe un "indietro" che non torna indietro
197	        if (str_contains((string) parse_url($url, PHP_URL_PATH), '/assets/')) {
198	            return null;
199	        }
200	
201	        return $url;
202	    }
203	
204	    /**
205	     * URL della lista (index) della resource Filament del record, da usare come
206	     * fallback quando manca un Referer valido. null se il record non ha una
207	     * resource registrata nel pannello o l'URL non è risolvibile.
208	     */
209	    private function resourceIndexUrl(): ?string
210	    {
211	        /** @var class-string<\Filament\Resources\Resource>|null $resource */
212	        $resource = \Filament\Facades\Filament::getModelResource($this->resolveOwner());
213	        if ($resource === null) {
214	            return null;
215	        }
216	
217	        try {
218	            $url = $resource::getUrl('index');
219	
220	            return $url ?: null;
221	        } catch (\Throwable) {
222	            return null;
223	        }
224	    }
225	
226	    /**
227	     * Risolve il record proprietario dalla coppia (morph alias, chiave).
228	     * 404 se il tipo non è mappato, il record non esiste o non è OwnsAssets.
229	     *
230	     * @return Model&OwnsAssets
231	     */
232	    public function resolveOwner(): Model
233	    {
234	        if ($this->ownerModel !== null) {
235	            return $this->ownerModel;
236	        }
237	
238	        $class = Relation::getMorphedModel($this->ownerType) ?? $this->ownerType;
239	        abort_unless(class_exists($class), 404);
240	
241	        /** @var class-string<Model> $class */
242	        $record = $class::query()->find($this->ownerKey);
243	        abort_unless($record instanceof OwnsAssets, 404);
244	
245	        return $this->ownerModel = $record;
246	    }
247	
248	    #[Override]
249	    public function getTitle(): string|Htmlable
250	    {
251	        $owner = $this->resolveOwner();
252	        $name = $owner->getAttribute('name');
253	        $key = $owner->getKey();
254	        $label = is_string($name) && $name !== ''
255	            ? $name
256	            : '#' . (is_scalar($key) ? (string) $key : '');
257	
258	        return (string) __('digital-hub::assets.title_for', ['owner' => $label]);
259	    }
260	
261	    /**
262	     * Nessun heading di pagina Filament: il titolo è renderizzato dalla barra del
263	     * finto modal nel blade. Tornando '' (vuoto) il componente di pagina non
264	     * disegna affatto l'header, evitando il doppione.
265	     */
266	    #[Override]
267	    public function getHeading(): string|Htmlable
268	    {
269	        return '';
270	    }
271	
272	    /**
273	     * Tutte le folder del record, caricate una sola volta per request.
274	     *
275	     * @return EloquentCollection<int, AssetFolder>
276	     */
277	    public function allFolders(): EloquentCollection
278	    {
279	        if ($this->folderCache !== null) {
280	            return $this->folderCache;
281	        }
282	
283	        return $this->folderCache = $this->resolveOwner()->allAssetFolders();
284	    }
285	
286	    /**
287	     * Seleziona la folder attiva (null = root). Ignora id non appartenenti al
288	     * record (es. manomissione del payload Livewire).
289	     */
290	    public function selectFolder(?int $folderId): void
291	    {
292	        // cambiando vista la selezione corrente non ha più senso
293	        $this->selectedAssetIds = [];
294	        $this->selectedFolderIds = [];
295	
296	        if ($folderId === null) {
297	            $this->activeFolderId = null;
298	
299	            return;
300	        }
301	
302	        if ($this->allFolders()->firstWhere('id', $folderId) !== null) {
303	            $this->activeFolderId = $folderId;
304	        }
305	    }
306	
307	    /**
308	     * Svuota la selezione corrente (pulsante "Annulla selezione").
309	     */
310	    public function clearAssetSelection(): void
311	    {
312	        $this->selectedAssetIds = [];
313	        $this->selectedFolderIds = [];
314	    }
315	
316	    /**
317	     * Seleziona tutti gli asset e le sottocartelle attualmente visibili nella
318	     * vista corrente (pulsante "Seleziona tutti", disponibile dopo la prima
319	     * selezione).
320	     */
321	    public function selectAllAssets(): void
322	    {
323	        $this->selectedAssetIds = $this->getAssets()
324	            ->map(function (Media $media): string {
325	                $key = $media->getKey();
326	
327	                return is_int($key) || is_string($key) ? (string) $key : '';
328	            })
329	            ->all();
330	
331	        $this->selectedFolderIds = $this->getSubfolders()
332	            ->map(fn (AssetFolder $folder): string => (string) $folder->id)
333	            ->all();
334	    }
335	
336	    /**
337	     * Sposta un media in una folder (o root) via drag-drop sull'albero (#16b).
338	     * `$mediaId` arriva come stringa dal dataTransfer; `$folderId` null = root.
339	     */
340	    public function moveAssetToFolder(mixed $mediaId, ?int $folderId): void
341	    {
342	        $media = $this->findOwnedMedia($mediaId);
343	        if ($media === null) {
344	            return;
345	        }
346	
347	        if ($folderId !== null && $this->findOwnedFolder($folderId) === null) {
348	            $folderId = null;
349	        }
350	
351	        $media->setAttribute('asset_folder_id', $folderId);
352	        $media->save();
353	
354	        Notification::make()->success()->title(__('digital-hub::assets.asset_moved'))->send();
355	    }
356	
357	    /**
358	     * Riordina un gruppo di folder fratelli via drag-drop nell'albero (#16b).
359	     * Riceve gli id nel nuovo ordine (da SortableJS) e riassegna `sort` per
360	     * posizione. Gli id estranei al record sono ignorati.
361	     *
362	     * @param array<int, int|string> $orderedIds
363	     */
364	    public function reorderFolders(array $orderedIds): void
365	    {
366	        foreach (array_values($orderedIds) as $index => $id) {
367	            $folder = $this->findOwnedFolder($id);
368	            if ($folder === null) {
369	                continue;
370	            }
371	
372	            if ($folder->sort !== $index) {
373	                $folder->sort = $index;
374	                $folder->save();
375	            }
376	        }
377	
378	        $this->folderCache = null;
379	    }
380	
381	    /**
382	     * Albero annidato delle folder del record per il pannello sinistro.
383	     * `children` è ricorsivamente la stessa struttura (non esprimibile come tipo
384	     * ricorsivo preciso in PHPDoc, quindi `mixed`).
385	     *
386	     * @return array<int, array{folder: AssetFolder, children: mixed}>
387	     */
388	    public function getFolderTree(): array
389	    {
390	        return $this->buildTree(null);
391	    }
392	
393	    /**
394	     * @return array<int, array{folder: AssetFolder, children: mixed}>
395	     */
396	    private function buildTree(?int $parentId): array
397	    {
398	        return $this->allFolders()
399	            ->where('parent_id', $parentId)
400	            ->map(fn (AssetFolder $folder): array => [
401	                'folder' => $folder,
402	                'children' => $this->buildTree($folder->id),
403	            ])
404	            ->values()
405	            ->all();
406	    }
407	
408	    /**
409	     * Sottocartelle dirette della folder attiva, da mostrare come tile nel
410	     * pannello destro insieme ai file. In root ("Home") sono le cartelle di
411	     * primo livello: la root si naviga come una cartella qualunque.
412	     *
413	     * @return \Illuminate\Support\Collection<int, AssetFolder>
414	     */
415	    public function getSubfolders(): \Illuminate\Support\Collection
416	    {
417	        return $this->allFolders()
418	            ->where('parent_id', $this->activeFolderId)
419	            ->values();
420	    }
421	
422	    /**
423	     * Catena dalla root alla folder attiva, per il breadcrumb. Vuota se siamo
424	     * in root. Se l'id attivo non esiste più (folder eliminata), resetta a root.
425	     *
426	     * @return list<AssetFolder>
427	     */
428	    public function getBreadcrumbTrail(): array
429	    {
430	        if ($this->activeFolderId === null) {
431	            return [];
432	        }
433	
434	        $folders = $this->allFolders();
435	        $trail = [];
436	        $id = $this->activeFolderId;
437	
438	        while ($id !== null) {
439	            $folder = $folders->firstWhere('id', $id);
440	            if (! $folder instanceof AssetFolder) {
441	                // folder eliminata sotto i piedi: torna a root
442	                $this->activeFolderId = null;
443	
444	                return [];
445	            }
446	
447	            array_unshift($trail, $folder);
448	            $id = $folder->parent_id;
449	        }
450	
451	        return $trail;
452	    }
453	
454	    /**
455	     * Media mostrati nel pannello destro: i soli media diretti della folder
456	     * attiva. In root ("Home") sono i file caricati direttamente in root
457	     * (nessuna folder assegnata), come in una cartella qualunque.
458	     *
459	     * @return \Illuminate\Support\Collection<int, \Spatie\MediaLibrary\MediaCollections\Models\Media>
460	     */
461	    public function getAssets(): \Illuminate\Support\Collection
462	    {
463	        $folder = $this->activeFolderId !== null
464	            ? $this->findOwnedFolder($this->activeFolderId)
465	            : null;
466	
467	        return $this->resolveOwner()->assetsInFolder($folder);
468	    }
469	
470	    // -- Preview delle cartelle (14b) -----------------------------------------
471	
472	    /** Numero massimo di miniature nel collage della tile cartella. */
473	    public const FOLDER_PREVIEW_LIMIT = 4;
474	
475	    /**
476	     * Miniature per le tile delle sottocartelle: per ogni sottocartella diretta
477	     * della folder attiva, fino a FOLDER_PREVIEW_LIMIT anteprime prese dai media
478	     * contenuti nella cartella o nei suoi discendenti (ordine order_column, come
479	     * la griglia). "Mostrabile" = ha il poster generato dal job, oppure è
480	     * un'immagine (l'originale è già leggero, mostrato anche se il media è
481	     * ancora `pending`: solo i metadati/poster mancano, non il file). I media
482	     * senza nulla di mostrabile vengono saltati: la tile ricade sull'icona finché
483	     * non c'è nulla da mostrare. `inProgress` marca le miniature il cui media non
484	     * ha ancora finito l'elaborazione, per l'overlay "in elaborazione" nel blade
485	     * (senza, un'immagine pending appare identica a una già completata).
486	     *
487	     * Derivata pura, niente da persistere: se il contenuto della cartella cambia
488	     * (spostamenti, delete, job completati) il prossimo render riflette lo stato.
489	     *
490	     * @return array<int, list<array{url: string, inProgress: bool}>> id sottocartella => miniature
491	     */
492	    public function getSubfolderPreviews(): array
493	    {
494	        $tileMap = $this->tileBySubtreeFolder();
495	
496	        $previews = [];
497	        foreach ($this->getSubfolders() as $subfolder) {
498	            $previews[$subfolder->id] = [];
499	        }
500	
501	        foreach ($this->subfolderMedia() as $media) {
502	            $tileId = $this->tileForMedia($media, $tileMap);
503	            if ($tileId === null || count($previews[$tileId]) >= self::FOLDER_PREVIEW_LIMIT) {
504	                continue;
505	            }
506	
507	            // stessa catena di fallback della card asset: poster → originale se immagine
508	            $url = AssetPreview::url($media)
509	                ?? (AssetFileType::fromMedia($media)->isImage() ? AssetUrl::original($media) : null);
510	
511	            if ($url !== null) {
512	                $previews[$tileId][] = [
513	                    'url' => $url,
514	                    'inProgress' => $this->assetStatus($media)?->isInProgress() ?? false,
515	                ];
516	            }
517	        }
518	
519	        return $previews;
520	    }
521	
522	    /**
523	     * Numero totale di file per ogni sottocartella visibile, discendenti
524	     * compresi, mostrato sotto il nome della tile. Conta sulla collezione già
525	     * caricata per le preview ({@see self::subfolderMedia()}): nessuna query
526	     * aggiuntiva.
527	     *
528	     * @return array<int, int> id sottocartella => numero di file nel sottoalbero
529	     */
530	    public function getSubfolderFileCounts(): array
531	    {
532	        $tileMap = $this->tileBySubtreeFolder();
533	
534	        $counts = [];
535	        foreach ($this->getSubfolders() as $subfolder) {
536	            $counts[$subfolder->id] = 0;
537	        }
538	
539	        foreach ($this->subfolderMedia() as $media) {
540	            $tileId = $this->tileForMedia($media, $tileMap);
541	            if ($tileId !== null) {
542	                $counts[$tileId]++;
543	            }
544	        }
545	
546	        return $counts;
547	    }
548	
549	    /**
550	     * Mappa ogni folder dei sottoalberi visibili (sottocartella diretta della
551	     * folder attiva o sua discendente) all'id della sottocartella-tile che la
552	     * contiene. Camminata sull'albero già in memoria.
553	     *
554	     * @return array<int, int>
555	     */
556	    private function tileBySubtreeFolder(): array
557	    {
558	        $map = [];
559	
560	        foreach ($this->getSubfolders() as $subfolder) {
561	            foreach ($this->descendantFolderIds($subfolder) as $id) {
562	                $map[$id] = $subfolder->id;
563	            }
564	        }
565	
566	        return $map;
567	    }
568	
569	    /**
570	     * Id della sottocartella-tile a cui il media afferisce (direttamente o via
571	     * discendenti), o null se fuori dai sottoalberi visibili.
572	     *
573	     * @param array<int, int> $tileMap da {@see self::tileBySubtreeFolder()}
574	     */
575	    private function tileForMedia(Media $media, array $tileMap): ?int
576	    {
577	        $folderId = $media->getAttribute('asset_folder_id');
578	
579	        return is_numeric($folderId) ? ($tileMap[(int) $folderId] ?? null) : null;
580	    }
581	
582	    /**
583	     * True se tra i media dei sottoalberi delle sottocartelle visibili ce n'è
584	     * almeno uno in lavorazione: estende il polling della griglia (che guarda
585	     * solo gli asset della folder attiva) così le preview delle tile cartella
586	     * compaiono da sole a job concluso.
587	     */
588	    public function hasProcessingInSubfolders(): bool
589	    {
590	        return $this->subfolderMedia()->contains(
591	            fn (Media $media): bool => $this->assetStatus($media)?->isInProgress() ?? false,
592	        );
593	    }
594	
595	    /**
596	     * Id della folder e di tutte le sue discendenti, camminando l'albero già
597	     * cachato in memoria ({@see self::allFolders()}): nessuna query aggiuntiva.
598	     *
599	     * @return list<int>
600	     */
601	    private function descendantFolderIds(AssetFolder $folder): array
602	    {
603	        $ids = [$folder->id];
604	
