612	    /**
613	     * Media contenuti nei sottoalberi delle sottocartelle della folder attiva,
614	     * in una sola query (niente N+1 sulle tile), cachati per la request.
615	     *
616	     * @return \Illuminate\Support\Collection<int, Media>
617	     */
618	    private function subfolderMedia(): \Illuminate\Support\Collection
619	    {
620	        if ($this->subfolderMediaCache !== null) {
621	            return $this->subfolderMediaCache;
622	        }
623	
624	        $ids = [];
625	        foreach ($this->getSubfolders() as $subfolder) {
626	            $ids = array_merge($ids, $this->descendantFolderIds($subfolder));
627	        }
628	
629	        if ($ids === []) {
630	            return $this->subfolderMediaCache = new \Illuminate\Support\Collection();
631	        }
632	
633	        $owner = $this->resolveOwner();
634	
635	        return $this->subfolderMediaCache = $owner->media()
636	            ->where('collection_name', $owner->assetsCollection())
637	            ->whereIn('asset_folder_id', $ids)
638	            ->orderBy('order_column')
639	            ->get()
640	            ->toBase()
641	            // narrowing per phpstan: la relazione media() è tipata sul Model base
642	            ->filter(fn ($media): bool => $media instanceof Media)
643	            ->values();
644	    }
