832	    /**
833	     * Carica uno o più file nella folder attiva (root se nessuna selezionata).
834	     * I file finiscono nella collection asset del record (disco scoped).
835	     */
836	    public function uploadAssetsAction(): Action
837	    {
838	        return Action::make('uploadAssets')
839	            ->label(__('digital-hub::assets.upload'))
840	            ->icon(Heroicon::OutlinedArrowUpTray)
841	            ->modalHeading(__('digital-hub::assets.upload_heading'))
842	            ->schema([
843	                FileUpload::make('files')
844	                    ->label(__('digital-hub::assets.files_field'))
845	                    ->multiple()
846	                    ->required()
847	                    ->storeFiles(false),
848	            ])
849	            ->action(function (array $data): void {
850	                $owner = $this->resolveOwner();
851	                $files = $data['files'] ?? [];
852	                if (! is_array($files)) {
853	                    return;
854	                }
855	
856	                $count = 0;
857	                foreach ($files as $file) {
858	                    if (! $file instanceof TemporaryUploadedFile) {
859	                        continue;
860	                    }
861	
862	                    $media = $owner->addMedia($file)
863	                        ->usingName(pathinfo($file->getClientOriginalName(), PATHINFO_FILENAME))
864	                        ->toMediaCollection($owner->assetsCollection());
865	                    $media->setAttribute('asset_folder_id', $this->activeFolderId);
866	
867	                    // autore: FK nullable verso l'utente + snapshot del nome (fallback
868	                    // se l'utente verrà eliminato → uploaded_by_id null per nullOnDelete)
869	                    /** @disregard P1013 */
870	                    $user = auth()->user();
871	                    $media->setAttribute('uploaded_by_id', $user?->getAuthIdentifier());
872	                    $media->setAttribute('uploaded_by_name', $user instanceof Model ? $user->getAttribute('name') : null);
873	
874	                    // l'elaborazione (metadati, dimensioni, future taglie) la fa un
875	                    // job in coda: il media entra "pending" finché il job non lo chiude
876	                    $media->setAttribute('processing_status', AssetProcessingStatus::Pending->value);
877	                    $media->save();
878	
879	                    $this->dispatchProcessing($media);
880	                    $count++;
881	                }
882	
883	                if ($count > 0) {
884	                    Notification::make()
885	                        ->success()
886	                        ->title(trans_choice('digital-hub::assets.assets_uploaded', $count, ['count' => $count]))
887	                        ->send();
888	                }
889	            });
890	    }
