1158	    /**
1159	     * Sezioni collassabili con i metadati estratti grezzi (`extracted_metadata`),
1160	     * un blocco per chiave presente (`common`/`exif`/`iptc`/`xmp`). I valori
1161	     * annidati (sezioni EXIF, liste IPTC) sono appiattiti in dot-notation perché
1162	     * il KeyValueEntry rende solo coppie chiave→scalare. Vuoto se non ci sono
1163	     * metadati (media non ancora processato).
1164	     *
1165	     * `$media` (già risolto dal chiamante, per decidere quali blocchi esistono)
1166	     * serve solo a stabilire QUALI sezioni costruire; il CONTENUTO di ciascuna
1167	     * (`KeyValueEntry::state()`) è una closure che rilegge `$mediaKey` a ogni
1168	     * render, così un reprocess successivo (nuovi metadati) si riflette senza
1169	     * dover riaprire il pannello.
1170	     *
1171	     * @return list<Section>
1172	     */
1173	    private function assetMetadataSections(int|string $mediaKey, Media $media): array
1174	    {
1175	        $metadata = ExtractedMetadata::forMedia($media);
1176	
1177	        $labels = [
1178	            'common' => __('digital-hub::assets.meta_block_common'),
1179	            'exif' => 'EXIF',
1180	            'iptc' => 'IPTC',
1181	            'xmp' => 'XMP',
1182	        ];
1183	
1184	        $sections = [];
1185	        foreach ($labels as $key => $label) {
1186	            $block = $metadata[$key] ?? null;
1187	            if (! is_array($block)) {
1188	                continue;
1189	            }
1190	
1191	            $flat = ExtractedMetadata::flatten($block);
1192	            if ($flat === []) {
1193	                continue;
1194	            }
1195	
1196	            $sections[] = Section::make($label)
1197	                ->heading('')
1198	                // ->collapsible()
1199	                // ->collapsed($key !== 'common') // i generali aperti, i blocchi grezzi chiusi
1200	                ->schema([
1201	                    Fieldset::make($label)
1202	                        ->columnSpanFull()
1203	                        ->columns(1)
1204	                        ->contained(false)
1205	                        ->schema([
1206	                            KeyValueEntry::make("meta_{$key}")
1207	                                ->hiddenLabel()
1208	                                ->state(function () use ($mediaKey, $key): array {
1209	                                    $media = $this->findOwnedMedia($mediaKey);
1210	                                    $block = $media === null ? null : (ExtractedMetadata::forMedia($media)[$key] ?? null);
1211	
1212	                                    return is_array($block) ? ExtractedMetadata::flatten($block) : [];
1213	                                })
1214	                                ->keyLabel(__('digital-hub::assets.meta_key'))
1215	                                ->valueLabel(__('digital-hub::assets.meta_value')),
1216	                        ]),
1217	                ]);
1218	        }
1219	
1220	        return $sections;
1221	    }
