1254	    /**
1255	     * Media su cui operano scarica/condividi/sposta/elimina: dal menu contestuale
1256	     * arriva il singolo `media` (id) o la singola `folder` (id, espansa nei media
1257	     * del suo sottoalbero) come argument, dalla barra multipla si usa la selezione
1258	     * corrente ($selectedAssetIds + $selectedFolderIds, cartelle espanse). Filtra
1259	     * gli id non appartenenti al record e deduplica (un file può essere selezionato
1260	     * sia direttamente sia dentro una cartella selezionata). È il punto in cui
1261	     * azioni singole e di gruppo condividono il target.
1262	     *
1263	     * @param array<array-key, mixed> $arguments
1264	     * @return list<Media>
1265	     */
1266	    private function actionMedia(array $arguments): array
1267	    {
1268	        if (array_key_exists('media', $arguments)) {
1269	            $item = $this->findOwnedMedia($arguments['media']);
1270	
1271	            return $item === null ? [] : [$item];
1272	        }
1273	
1274	        if (array_key_exists('folder', $arguments)) {
1275	            $folder = $this->findOwnedFolder($arguments['folder']);
1276	
1277	            return $folder === null ? [] : $this->subtreeMedia([$folder]);
1278	        }
1279	
1280	        // selezione mista: file spuntati + contenuto delle cartelle spuntate
1281	        $byKey = [];
1282	        foreach ($this->selectedAssetIds as $id) {
1283	            $item = $this->findOwnedMedia($id);
1284	            $key = $item?->getKey();
1285	            if ($item !== null && (is_int($key) || is_string($key))) {
1286	                $byKey[(string) $key] = $item;
1287	            }
1288	        }
1289	
1290	        $folders = [];
1291	        foreach ($this->selectedFolderIds as $id) {
1292	            $folder = $this->findOwnedFolder($id);
1293	            if ($folder !== null) {
1294	                $folders[] = $folder;
1295	            }
1296	        }
1297	        foreach ($this->subtreeMedia($folders) as $item) {
1298	            $key = $item->getKey();
1299	            if (is_int($key) || is_string($key)) {
1300	                $byKey[(string) $key] = $item;
1301	            }
1302	        }
1303	
1304	        return array_values($byKey);
1305	    }
