1307	    /**
1308	     * Media contenuti nei sottoalberi delle folder date (discendenti compresi),
1309	     * in una sola query, nell'ordine della griglia. È l'espansione "cartella →
1310	     * file" usata da scarica/condividi su cartelle.
1311	     *
1312	     * @param list<AssetFolder> $folders
1313	     * @return list<Media>
1314	     */
1315	    private function subtreeMedia(array $folders): array
1316	    {
1317	        $ids = [];
1318	        foreach ($folders as $folder) {
1319	            $ids = array_merge($ids, $this->descendantFolderIds($folder));
1320	        }
1321	
1322	        if ($ids === []) {
1323	            return [];
1324	        }
1325	
1326	        $owner = $this->resolveOwner();
1327	
1328	        return array_values($owner->media()
1329	            ->where('collection_name', $owner->assetsCollection())
1330	            ->whereIn('asset_folder_id', array_unique($ids))
1331	            ->orderBy('order_column')
1332	            ->get()
1333	            ->toBase()
1334	            // narrowing per phpstan: la relazione media() è tipata sul Model base
1335	            ->filter(fn ($media): bool => $media instanceof Media)
1336	            ->all());
1337	    }
