74	                continue;
75	            }
76	
77	            // stessa catena di fallback della card asset: poster → originale se immagine
78	            $url = AssetPreview::url($media)
79	                ?? (AssetFileType::fromMedia($media)->isImage() ? AssetUrl::original($media) : null);
80	
81	            if ($url !== null) {
82	                $previews[$tileId][] = [
83	                    'url' => $url,
84	                    'inProgress' => $this->isInProgress($media),
85	                ];
86	            }
87	        }
88	
89	        return $previews;
90	    }
