92	    /**
93	     * Numero totale di file per ogni sottocartella visibile, discendenti compresi,
94	     * mostrato sotto il nome della tile. Conta sulla collezione già caricata per
95	     * le preview: nessuna query aggiuntiva.
96	     *
97	     * @return array<int, int> id sottocartella => numero di file nel sottoalbero
98	     */
99	    public function fileCounts(): array
100	    {
101	        $tileMap = $this->tileMap();
102	
103	        $counts = [];
104	        foreach ($this->subfolders as $subfolder) {
105	            $counts[$subfolder->id] = 0;
106	        }
107	
108	        foreach ($this->media() as $media) {
109	            $tileId = $this->tileForMedia($media, $tileMap);
110	            if ($tileId !== null) {
111	                $counts[$tileId]++;
112	            }
113	        }
114	
115	        return $counts;
116	    }
117	
118	    /**
119	     * True se tra i media dei sottoalberi delle sottocartelle visibili ce n'è
120	     * almeno uno in lavorazione: estende il polling della griglia (che guarda solo
121	     * gli asset della folder attiva) così le preview delle tile compaiono da sole
122	     * a job concluso.
123	     */
124	    public function hasProcessing(): bool
125	    {
126	        return $this->media()->contains(fn (Media $media): bool => $this->isInProgress($media));
127	    }
128	
129	    /**
130	     * Media contenuti nei sottoalberi delle sottocartelle, in una sola query
131	     * (niente N+1 sulle tile), caricati una volta e tenuti in memoria.
132	     *
133	     * @return Collection<int, Media>
134	     */
135	    private function media(): Collection
136	    {
137	        if ($this->mediaCache !== null) {
138	            return $this->mediaCache;
139	        }
140	
141	        $ids = [];
142	        foreach ($this->subfolders as $subfolder) {
143	            $ids = array_merge($ids, $this->tree->descendantIds($subfolder->id));
144	        }
145	
146	        return $this->mediaCache = $this->resolver->mediaInFolders($ids);
147	    }
148	
149	    /**
150	     * Mappa ogni folder dei sottoalberi visibili (sottocartella diretta o sua
151	     * discendente) all'id della sottocartella-tile che la contiene. Camminata
152	     * sull'albero già in memoria.
153	     *
154	     * @return array<int, int>
155	     */
156	    private function tileMap(): array
157	    {
158	        if ($this->tileMapCache !== null) {
159	            return $this->tileMapCache;
160	        }
161	
162	        $map = [];
163	        foreach ($this->subfolders as $subfolder) {
164	            foreach ($this->tree->descendantIds($subfolder->id) as $id) {
165	                $map[$id] = $subfolder->id;
166	            }
167	        }
168	
169	        return $this->tileMapCache = $map;
170	    }
171	
172	    /**
173	     * Id della sottocartella-tile a cui il media afferisce (direttamente o via
174	     * discendenti), o null se fuori dai sottoalberi visibili.
175	     *
176	     * @param array<int, int> $tileMap da {@see self::tileMap()}
177	     */
178	    private function tileForMedia(Media $media, array $tileMap): ?int
179	    {
180	        $folderId = $media->getAttribute('asset_folder_id');
181	
182	        return is_numeric($folderId) ? ($tileMap[(int) $folderId] ?? null) : null;
183	    }
184	
185	    /**
186	     * Stato di elaborazione "in corso" del media (media legacy o di altre
187	     * collection, senza `processing_status`, contano come non in corso).
188	     */
189	    private function isInProgress(Media $media): bool
190	    {
191	        $raw = $media->getAttribute('processing_status');
192	
193	        return is_string($raw) && (AssetProcessingStatus::tryFrom($raw)?->isInProgress() ?? false);
194	    }
