public function infoAssetAction(): Action
{
    return Action::make('infoAsset')
        ->label(__('digital-hub::assets.info'))
        ->icon(Heroicon::OutlinedInformationCircle)
        ->slideOver()
        ->modalHeading(__('digital-hub::assets.info_heading'))
        ->modalSubmitAction(false)
        ->modalCancelActionLabel(__('digital-hub::assets.close'))
        // "Chiudi" spinto a destra (ms-auto) nel footer, che di default
        // allinea tutto a sinistra (vedi modalFooterActionsAlignment sotto):
        // le azioni sul file restano a sinistra, "Chiudi" isolato a destra.
        ->modalCancelAction(fn (Action $action): Action => $action->extraAttributes(['class' => 'ms-auto']))
        // azioni sul file (14e) nel footer dello slideover: riusano le
        // stesse action del menu contestuale, con `media` già in argument.
        ->extraModalFooterActions(function (array $arguments): array {
            $media = $this->findOwnedMedia($arguments['media'] ?? null);
            if ($media === null) {
                return [];
            }
            return [
                $this->downloadAssetAction()->button()->color('gray')->arguments(['media' => $media->getKey()]),
                $this->shareAssetAction()->button()->color('gray')->arguments(['media' => $media->getKey()]),
                $this->duplicateAssetAction()->button()->color('gray')->arguments(['media' => $media->getKey()]),
                $this->deleteAssetAction()->button()->arguments(['media' => $media->getKey()]),
            ];
        })
        ->modalFooterActionsAlignment(Alignment::Start)
        // "Sostituisci file" (14d) non va nel footer ma in overlay sopra la
        // preview (vedi schema sotto): va comunque registrata come modal
        // action del genitore `infoAsset`, altrimenti Livewire non riesce a
        // risolverla quando viene mountata mentre infoAsset è già aperto
        // (mount nidificato — stesso motivo per cui il footer usa
        // extraModalFooterActions invece di un'action "libera").
        ->registerModalActions([
            fn (array $arguments): Action => $this->replaceAssetFileAction()->arguments(['media' => $arguments['media'] ?? null]),
        ])
        ->schema(function (Schema $schema, array $arguments): Schema {
            $media = $this->findOwnedMedia($arguments['media'] ?? null);
            $mediaKey = $media?->getKey();

            return $schema->components($media === null || $mediaKey === null ? [] : [
                Grid::make(['default' => 1, 'lg' => 2])->schema([
                    // colonna sinistra: anteprima con "sostituisci file" in overlay sopra
                    // (sull'asse z, non sopra nel layout) + tab info/metadati. Il bottone qui
                    // è solo il trigger visivo (Actions::make, posizionato via extraAttributes
                    // su un contenitore `relative`); la risoluzione del mount nidificato è
                    // affidata a ->registerModalActions() sopra, non alla presenza nello schema.
                    //
                    // wire:poll mentre il job non ha finito (stesso pattern della griglia,
                    // vedi asset-manager.blade.php): senza, dopo un "sostituisci file" lo
                    // slideover resterebbe fermo su "in elaborazione" finché non lo si
                    // riapre — il poll lo aggiorna da solo a completamento.
                    Group::make([

                        // preview asset con pulsante "sostituisci"
                        Group::make([
                            ViewEntry::make('preview')
                                ->hiddenLabel()
                                // Closure, non un array statico: questo schema (di 'infoAsset') viene
                                // costruito una sola volta al mount e Filament lo mette in cache
                                // (mountedActionSchema) per tutta la vita dell'action montata — non si
                                // ricostruisce da solo dopo "sostituisci file" (mount nidificato che
                                // cambia il media sotto). `view()` valuta però i suoi dati a ogni
                                // render (non al build dello schema): rifacendo qui il fetch di
                                // $media dal solo id, la preview resta sempre aggiornata anche se il
                                // resto dello schema è congelato.
                                ->view('digital-hub::filament.partials.asset-preview', function () use ($mediaKey): array {
                                    $media = $this->findOwnedMedia($mediaKey);

                                    return $media === null ? [] : [
                                        'media' => $media,
                                        // URL protetti da sessione: nel pannello l'utente è autenticato
                                        'posterUrl' => AssetPreview::url($media),
                                        'originalUrl' => AssetUrl::original($media),
                                    ];
                                }),
                            Actions::make([
                                $this->replaceAssetFileAction()
                                ->button()->color('primary')->arguments(['media' => $mediaKey])
                                ->extraAttributes(['class' => 'absolute bottom-10 left-1/2 -translate-1/2 z-10']),
                            ]),
                        ])->extraAttributes(['class' => 'relative col-sx-preview']),

                        // tab informative
                        // @phpstan-ignore argument.type (getKey() è mixed, ma su Media è sempre int|string)
                        $this->assetInfoTabs($mediaKey),

                    ])->extraAttributes(function () use ($mediaKey): array {
                        $media = $this->findOwnedMedia($mediaKey);
                        $isInProgress = $media !== null && ($this->assetStatus($media)?->isInProgress() ?? false);

                        return $isInProgress ? ['wire:poll.3s' => true] : [];
                    }),

                    // colonna destra: nome editabile (etichetta `name` di Spatie Media,
                    // non il file fisico — salvataggio live al blur, niente submit del form)
                    Group::make([
                        TextInput::make('name')
                            ->label(__('digital-hub::assets.display_name'))
                            ->default($media->name)
                            ->required()
                            ->maxLength(255)
                            ->live(onBlur: true)
                            ->afterStateUpdated(function (?string $state) use ($media): void {
                                if (! is_string($state) || $state === '' || $state === $media->name) {
                                    return;
                                }

                                $media->name = $state;
                                $media->save();

                                Notification::make()->success()->title(__('digital-hub::assets.name_updated'))->send();
                            }),
                    ]),
                ]),
            ]);
        });
}

/**
 * Tab del pannello info: "Informazioni" (metadati curati/normalizzati) e
 * "Metadati completi" (`extracted_metadata` grezzo, un blocco per tipo). Il
 * secondo tab compare solo se ci sono metadati estratti.
 *
 * Prende l'id del media, non l'oggetto: lo schema di 'infoAsset' viene
 * costruito una sola volta al mount e resta in cache (Filament,
 * `mountedActionSchema`) per tutta la vita dell'action montata — non si
 * ricostruisce da solo dopo "sostituisci file" (mount nidificato che cambia
 * il media sotto). I VALORI delle entry sono quindi closure che rifanno il
 * fetch a ogni render (vedi assetInfoEntries/assetMetadataSections); la sola
 * cosa che resta congelata all'apertura del pannello è la PRESENZA del tab
 * "Metadati completi" (decisa qui, una volta) — se il replace cambia tipo di
 * file passando da "senza metadati" a "con metadati" o viceversa, il tab
 * segue lo stato di quando il pannello è stato aperto, non quello corrente.
 */
private function assetInfoTabs(int|string $mediaKey): Tabs
{
    // prima tab con informazioni"
    $tabs = [
        Tab::make(__('digital-hub::assets.info_tab_summary'))
            ->schema($this->assetInfoEntries($mediaKey)),
    ];

    // seconda tab con le sezioni degli altri gruppi di metadati
    $media = $this->findOwnedMedia($mediaKey);
    $sections = $media === null ? [] : $this->assetMetadataSections($mediaKey, $media);
    if ($sections !== []) {
        $tabs[] = Tab::make(__('digital-hub::assets.info_tab_full'))
            ->schema($sections);
    }

    return Tabs::make()->tabs($tabs);
}

/**
 * Sezioni collassabili con i metadati estratti grezzi (`extracted_metadata`),
 * un blocco per chiave presente (`common`/`exif`/`iptc`/`xmp`). I valori
 * annidati (sezioni EXIF, liste IPTC) sono appiattiti in dot-notation perché
 * il KeyValueEntry rende solo coppie chiave→scalare. Vuoto se non ci sono
 * metadati (media non ancora processato).
 *
 * `$media` (già risolto dal chiamante, per decidere quali blocchi esistono)
 * serve solo a stabilire QUALI sezioni costruire; il CONTENUTO di ciascuna
 * (`KeyValueEntry::state()`) è una closure che rilegge `$mediaKey` a ogni
 * render, così un reprocess successivo (nuovi metadati) si riflette senza
 * dover riaprire il pannello.
 *
 * @return list<Section>
 */
private function assetMetadataSections(int|string $mediaKey, Media $media): array
{
    $metadata = ExtractedMetadata::forMedia($media);

    $labels = [
        'common' => __('digital-hub::assets.meta_block_common'),
        'exif' => 'EXIF',
        'iptc' => 'IPTC',
        'xmp' => 'XMP',
    ];

    $sections = [];
    foreach ($labels as $key => $label) {
        $block = $metadata[$key] ?? null;
        if (! is_array($block)) {
            continue;
        }

        $flat = ExtractedMetadata::flatten($block);
        if ($flat === []) {
            continue;
        }

        $sections[] = Section::make($label)
            ->heading('')
            // ->collapsible()
            // ->collapsed($key !== 'common') // i generali aperti, i blocchi grezzi chiusi
            ->schema([
                Fieldset::make($label)
                    ->columnSpanFull()
                    ->columns(1)
                    ->contained(false)
                    ->schema([
                        KeyValueEntry::make("meta_{$key}")
                            ->hiddenLabel()
                            ->state(function () use ($mediaKey, $key): array {
                                $media = $this->findOwnedMedia($mediaKey);
                                $block = $media === null ? null : (ExtractedMetadata::forMedia($media)[$key] ?? null);

                                return is_array($block) ? ExtractedMetadata::flatten($block) : [];
                            })
                            ->keyLabel(__('digital-hub::assets.meta_key'))
                            ->valueLabel(__('digital-hub::assets.meta_value')),
                    ]),
            ]);
    }

    return $sections;
}

/**
 * Voci (sola lettura) del tab "Informazioni": metadati curati/normalizzati,
 * dalla fonte unica {@see AssetSummary} (condivisa con la gallery di share).
 * Ogni valore è una closure che rilegge il media da `$mediaKey` a ogni
 * render (vedi assetInfoTabs): il NUMERO di entry resta quello di quando il
 * pannello è stato aperto (es. se il replace introduce/rimuove la voce
 * "Risoluzione" cambiando tipo di file, non compare/scompare da sola).
 *
 * @return list<Entry>
 */
private function assetInfoEntries(int|string $mediaKey): array
{
    $media = $this->findOwnedMedia($mediaKey);
    if ($media === null) {
        return [];
    }

    $entries = [];
    foreach (AssetSummary::forMedia($media) as $i => $row) {
        $entries[] = TextEntry::make("info_{$i}")
            ->label($row['label'])
            ->state(function () use ($mediaKey, $i): string {
                $media = $this->findOwnedMedia($mediaKey);

                return $media === null ? '' : (AssetSummary::forMedia($media)[$i]['value'] ?? '');
            });
    }

    return $entries;
}

